edits.to:
/* Mobile venue copy leads; athletes and basket remain below the CTA. */
#venues-scene .mskba-v3-venues__container {
  padding-top: 28px !important;
  padding-bottom: 74px !important;
}
#venues-scene .mskba-v3-venues__copy {
  position: relative;
  z-index: 30;
  padding-top: 20px !important;
  margin-top: 0 !important;
}
#venues-scene .mskba-v3-venues__ghost {
  top: -7px !important;
  opacity: .14;
  pointer-events: none;
}
#venues-scene .mskba-v3-venues__hoop { top: clamp(250px, 67vw, 310px) !important; }
#venues-scene .mskba-v3-venues__features {
  margin-top: clamp(440px, 100vw, 650px) !important;
}
#venues-scene .mskba-v3-venues__defender {
  top: clamp(265px, 70vw, 330px) !important;
}
#venues-scene .mskba-v3-venues__shooter-frame > .mskba-v3-venues__shooter {
  top: clamp(260px, 69vw, 325px) !important;
}
